sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    gs.addInfoMessage("current: " + JSON.stringify(current));
    gs.addInfoMessage("current sys id = " + current.getUniqueValue());

    if (!current.getValue('short_description')) {
        gs.addInfoMessage("Short description is empty");

        var gr = new GlideRecord('sc_req_item');
        gr.addQuery('request', current.sys_id);
		gr.addEncodedQuery('request.number=' + current.number);
        // gr.query();

        if (gr.next()) {
			gs.info('Found matching sc_req_item record');
			// gs.addInfoMessage('goes into if gr.next()');
			// gs.addInfoMessage('gr = ' + gr.getDisplayValue('cat_item'));
			gs.info('cat_item = ' + gr.getDisplayValue('cat_item'));

            // update short_description 
			current.setValue('short_description', "Request for " + gr.getDisplayValue('cat_item'));
        }
    }

    if (!current.getValue(catalog_name)) {
		var catItemGR = new GlideRecord('sc_cat_item');
		if (catItemGR.get(gr.cat_item)) {
			current.setValue('catalog_name', catItemGR.category.name);
		}
    }
})(current, previous);
